        // Built-in public CORS proxy list
        const BUILTIN_PROXIES = [
            'https://corsproxy.io/?',
            'https://api.allorigins.win/raw?url=',
            'https://cors-anywhere.herokuapp.com/'
        ];
        let currentProxyIndex = 0;

        function getEffectiveProxyUrl() {
            if (State.proxyMode === 'custom') {
                const custom = (document.getElementById('corsProxyUrl').value || '').trim();
                if (custom && !custom.includes('your-worker') && !custom.includes('placeholder'))
                    return custom;
                return null;
            }
            if (State.proxyMode === 'builtin') return BUILTIN_PROXIES[currentProxyIndex];
            return null; // direct mode
        }

        function rotateProxy() {
            currentProxyIndex = (currentProxyIndex + 1) % BUILTIN_PROXIES.length;
            UI.updateProxyStatus();
        }

        function smartFetch(url, options = {}) {
            const proxy = getEffectiveProxyUrl();
            const proxyUrl = proxy ? proxy + encodeURIComponent(url) : url;
            return fetch(proxyUrl, options);
        }
        // Try direct first, fall back to proxy on CORS error
        async function smartFetchWithFallback(url, options = {}) {
            // If proxy mode is 'direct', try direct first
            if (State.proxyMode === 'direct') {
                try {
                    const resp = await fetch(url, options);
                    if (resp.ok) return resp;
                    if (resp.status === 403 || resp.status === 429) {
                        // Try built-in proxy as fallback
                        const fbProxy = BUILTIN_PROXIES[0];
                        const fbUrl = fbProxy + encodeURIComponent(url);
                        return await fetch(fbUrl, options);
                    }
                    return resp;
                } catch (e) {
                    // CORS error - try built-in proxy
                    if (e.message.includes('CORS') || e.message.includes('fetch') || e.name ===
                        'TypeError') {
                        const fbProxy = BUILTIN_PROXIES[0];
                        const fbUrl = fbProxy + encodeURIComponent(url);
                        return await fetch(fbUrl, options);
                    }
                    throw e;
                }
            }
            // Other modes: use smartFetch directly
            return smartFetch(url, options);
        }

        // ====================== KNOWN QUOTE CURRENCIES ======================
        const KNOWN_QUOTES = [
            'USDT', 'USDC', 'BUSD', 'GUSD', 'USD', 'BTC', 'ETH', 'BNB', 'SOL', 'EUR', 'GBP', 'JPY',
            'KRW', 'AUD', 'CAD', 'CHF', 'RUR', 'RUB', 'INR', 'TRY', 'BRL', 'IDR', 'DAI', 'SGD', 'PLN',
            'UAH', 'AED', 'BETH', 'ZEC', 'ZRX', 'RAY', 'STRK', 'MATIC', 'DOT', 'TRB', 'TON', 'PI',
