                document.getElementById('quantumFundLocked').textContent = '$' + (State.lFund || 0).toFixed(2);
                document.getElementById('bankroll').textContent = '$' + State.bankroll.toFixed(2);
                const pnl = State.bankroll - 10000;
                document.getElementById('pnl').innerHTML =
                    `$${pnl.toFixed(2)} (${((pnl/10000)*100).toFixed(2)}%)`;
                document.getElementById('pnl').style.color = pnl >= 0 ? 'var(--green)' : '#ff4444';
            },
            renderOpp(opp, targetId, isMega = false) {
                const container = document.getElementById(targetId);
                if (!container) return;
                const cls = isMega ? 'mega' : (opp.profitPercent > 50 ? 'suspicious' : '');
                const html =
                    `<div class="opportunity ${cls}" onclick="UI.openTradeModal('${encodeURIComponent(JSON.stringify(opp))}')">
            <strong>${opp.type.toUpperCase()} +${opp.profitPercent.toFixed(2)}%</strong>
            <div class="path-visual">${opp.path.join(' → ')}</div>
            <div>Max: $${opp.maxTradeSize.toFixed(2)} | Profit: $${opp.actualProfit.toFixed(2)}</div></div>`;
                container.innerHTML = html + container.innerHTML;
            },
            openTradeModal(oppStr) {
                const opp = JSON.parse(decodeURIComponent(oppStr));
                const bet = parseFloat(document.getElementById('betInput').value) || 1000;
                const tradeSize = Math.min(opp.maxTradeSize, bet);
                let runningTotal = tradeSize;
                let mathString = `Start: $${tradeSize.toFixed(2)}<br>`;
                const detailsHtml = opp.edges.map((edge, i) => {
                    const prev = runningTotal;
                    runningTotal *= edge.rate;
                    mathString +=
                        `Hop ${i+1}: $${prev.toFixed(2)} × ${edge.rate.toFixed(6)} → $${runningTotal.toFixed(2)}<br>`;
                    const depthPct = Math.min(1, tradeSize / (edge.liquidity + 1));
                    const depthColor = depthPct > 0.8 ? '#ff4444' : depthPct > 0.5 ? '#ffaa00' :
                        'var(--cyan)';
                    return `<div style="margin:5px 0;padding:8px;background:#111;border-radius:5px;">
            <strong>${opp.path[i]} → ${opp.path[i+1]}</strong> <span class="chip">${edge.exchangeType.toUpperCase()}</span>
            <div class="depth-chart">${Array.from({length:10},(_,j)=>{const l=(j+1)/10;return `<div class="depth-bar" style="height:${l<=depthPct?25:5}px;background:${l<=depthPct?depthColor:'#333'};"></div>`;}).join('')}</div>
            <div style="font-size:9px;">Liq: $${edge.liquidity.toFixed(0)} | Depth: ${(depthPct*100).toFixed(1)}%</div></div>`;
                }).join('');
                mathString +=
                    `<strong style="color:var(--green);">💰 Final: $${runningTotal.toFixed(2)}</strong>`;
                document.getElementById('tradeDetails').innerHTML =
                    `<p>🔄 ${opp.path.join(' → ')}</p><p>💵 Trade: $${tradeSize.toFixed(2)}</p>${detailsHtml}`;
                document.getElementById('compoundingMath').innerHTML =
                    `<h4>📐 Compounding (${opp.edges.length} hops)</h4>${mathString}`;
                document.getElementById('executeTradeBtn').onclick = () => {
                    closeModal();
                    Engine.executeTrade(opp, tradeSize, runningTotal - tradeSize);
                };
                document.getElementById('tradeModal').style.display = 'flex';
            },
            closeModal() { document.getElementById('tradeModal').style.display = 'none'; },
            updateSlotDepthLabel() {
                document.getElementById('slotDepthLabel').textContent = document.getElementById('pathInput')
                    .value;
            },
            renderFiatCheckboxes() {
                const container = document.getElementById('fiatCheckboxes');
                const allFiats = ['RUR', 'INR', 'EUR', 'GBP', 'RUB', 'JPY', 'CNY', 'KRW', 'AUD', 'CAD', 'CHF',
                    'AED'
                ];
                container.innerHTML = '';
                allFiats.forEach(f => {
                    const checked = State.selectedFiats.has(f) ? 'checked' : '';
                    container.innerHTML +=
                        `<label><input type="checkbox" value="${f}" ${checked} onchange="UI.toggleFiat('${f}')"> ${f}</label>`;
                });
            },
            toggleFiat(fiat) {
                State.selectedFiats.has(fiat) ? State.selectedFiats.delete(fiat) : State.selectedFiats.add(
                    fiat);
                State.save();
                if (Object.keys(State.forexRates).length === 0 && document.getElementById('scanBtn')
                    .disabled === false) fetchForexRates();
            },
            onProxyChange() {
                const mode = document.getElementById('proxySelect').value;
                State.proxyMode = mode;
                document.getElementById('corsProxyUrl').style.display = mode === 'custom' ? 'inline-block' :
                    'none';
                this.updateProxyStatus();
                State.save();
            },
            updateProxyStatus() {
                const el = document.getElementById('proxyStatusMsg');
                if (!el) return;
                const mode = State.proxyMode;
                if (mode === 'direct') el.innerHTML =
                    '<span style="color:var(--green);">⚡ Direct mode – CORS-friendly exchanges work natively. Proxy used as fallback.</span>';
                else if (mode === 'builtin') el.innerHTML =
                    `<span style="color:var(--cyan);">🔁 Built-in proxy: ${BUILTIN_PROXIES[currentProxyIndex]} (rotates on failure)</span>`;
                else el.innerHTML =
                    '<span style="color:var(--gold);">📝 Custom proxy mode.</span>';
            },
            renderTradeLedger() {
                const el = document.getElementById('tradeLedger');
                if (!el) return;
                if (State.tradeLedger.length === 0) { el.innerHTML =
                        '<span style="color:#666;">No trades executed yet.</span>'; return; }
                el.innerHTML = State.tradeLedger.map(e =>
                    `<div style="margin:3px 0;padding:4px;background:#0a0a1a;border-radius:4px;">
          <span style="color:#888;">${e.time.slice(11,19)}</span>
          <span style="color:var(--cyan);">${e.type.toUpperCase()}</span>
          <span style="color:#aaa;">${e.path}</span>
          <span style="color:${e.profit>=0?'var(--green)':'#ff4444'};">$${e.profit.toFixed(2)}</span>
          </div>`).join('');
            }
        };

        function closeModal() { UI.closeModal(); }

        function saveProxyConfig() { State.proxyMode = document.getElementById('proxySelect').value;
            State.customProxyUrl = document.getElementById('corsProxyUrl').value;
