        }

        function handleKrakenWS(e) {
            try {
                const msg = JSON.parse(e.data);
                if (!Array.isArray(msg) || msg.length < 2) return;
                const ticker = msg[1];
                if (ticker && ticker.b && ticker.a) {
                    const pair = msg[3];
                    const parsed = parsePairSymbol(pair);
