                .writeText(`🎰 ${mega.profitPercent.toFixed(2)}% arb on QuanTM FOAM!`);
                log('📤 Copied!', 'success'); } else log('No jackpot to share', 'warning'); }

        function toggleTheme() { document.body.style.filter = document.body.style.filter ===
            'hue-rotate(180deg)' ? 'none' : 'hue-rotate(180deg)'; }

        function openCreateCoinModal() { if (State.level < 5) { alert('Need level 5 to create coins!'); return; }
            document.getElementById('createCoinModal').style.display = 'flex'; }

