    <script>
        // ==================== AUDIO & PARTICLES ====================
        const audioCtx = new(window.AudioContext || window.webkitAudioContext)();
        function playTone(f, d, t = 'square', v = 0.08) {
            const o = audioCtx.createOscillator(), g = audioCtx.createGain();
            o.type = t; o.frequency.value = f;
            g.gain.setValueAtTime(v, audioCtx.currentTime);
            g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + d);
            o.connect(g); g.connect(audioCtx.destination);
            o.start(); o.stop(audioCtx.currentTime + d);
        }
        function playSpin() { playTone(800, 0.1, 'sawtooth', 0.04); }
        function playWin() { playTone(523, 0.12); setTimeout(() => playTone(659, 0.12), 120); setTimeout(() => playTone(784, 0.2), 240); }
        function playJackpot() { [523, 659, 784, 1047].forEach((f, i) => setTimeout(() => playTone(f, 0.25, 'square', 0.12), i * 140)); }
        function playReelTick() { playTone(200 + Math.random() * 400, 0.03, 'sine', 0.02); }
        const canvas = document.getElementById('particleCanvas'), ctx = canvas.getContext('2d');
        let particles = [];
        function resize() { canvas.width = innerWidth; canvas.height = innerHeight; }
        window.addEventListener('resize', resize); resize();
        class Particle { constructor(x, y, vx, vy, c, l) { this.x = x; this.y = y; this.vx = vx; this.vy = vy; this.color = c; this.life = l; } }
        function anim() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            for (let i = particles.length - 1; i >= 0; i--) {
                const p = particles[i]; p.x += p.vx; p.y += p.vy; p.vy += 0.08; p.life -= 0.015;
                ctx.fillStyle = p.color; ctx.globalAlpha = Math.max(0, p.life); ctx.fillRect(p.x, p.y, 4, 4);
                if (p.life <= 0) particles.splice(i, 1);
            }
            requestAnimationFrame(anim);
        }
        anim();
        function confetti(x, y, n = 35) {
            const cols = ['#ff00ff', '#00ff00', '#ffd700', '#00ffaa', '#ff4444', '#00f0ff'];
            for (let i = 0; i < n; i++) particles.push(new Particle(x, y, (Math.random() - 0.5) * 9, (Math.random() - 0.5) * 8 - 4, cols[Math.floor(Math.random() * cols.length)], 0.7 + Math.random() * 0.5));
        }

        // ==================== STATE ====================
        const State = {
            bankroll: 10000, matrix: 0, level: 1, qFund: 0, lFund: 0, liveMode: false, userCoins: [],
            exchanges: {}, allPairs: [], graph: {}, triangles: [],
            opportunities: { mega: [], triangular: [], bellman: [], suspicious: [] },
            stats: { totalPairs: 0, graphNodes: 0, graphEdges: 0, triangleCount: 0, wsBytes: 0, oppCount: 0 },
            selectedIntraExchanges: new Set(),
            selectedFiats: new Set(['RUR', 'INR', 'EUR', 'GBP', 'RUB']),
            liveScanInterval: null, liveScanActive: false,
            forexRates: {}, forexLastFetch: 0,
            wsTickers: {}, tradeLedger: [],
            proxyMode: 'direct', customProxyUrl: '',
            lastTradeExecTime: 0,  // anti-duplication debounce
            load() {
                try {
                    const s = JSON.parse(localStorage.getItem('qfoam_v22final'));
                    if (s) {
                        this.bankroll = s.bankroll || 10000; this.matrix = s.matrix || 0; this.level = s.level || 1;
                        this.qFund = s.qFund || 0; this.lFund = s.lFund || 0; this.liveMode = s.liveMode || false;
                        this.userCoins = s.userCoins || [];
                        if (s.selectedIntraExchanges) this.selectedIntraExchanges = new Set(s.selectedIntraExchanges);
                        if (s.forexRates) this.forexRates = s.forexRates;
                        if (s.selectedFiats) this.selectedFiats = new Set(s.selectedFiats);
                        if (s.tradeLedger) this.tradeLedger = s.tradeLedger.slice(-15);
                        if (s.proxyMode) this.proxyMode = s.proxyMode;
                        if (s.customProxyUrl) this.customProxyUrl = s.customProxyUrl;
                        if (s.forexLastFetch) this.forexLastFetch = s.forexLastFetch;
                    }
                } catch (e) {}
                document.getElementById('solAddress').value = localStorage.getItem('wallet_sol') || '';
                document.getElementById('ethAddress').value = localStorage.getItem('wallet_eth') || '';
                document.getElementById('pumpToken').value = localStorage.getItem('pumpfun_token') || '';
                document.getElementById('basketInput').value = localStorage.getItem('basket') || 'USDT,BTC,ETH,DOGE,SHIB,SOL';
                document.getElementById('pathInput').value = localStorage.getItem('pathDepth') || 5;
                document.getElementById('pathSlider').value = document.getElementById('pathInput').value;
                document.getElementById('liveToggle').checked = this.liveMode;
                document.getElementById('proxySelect').value = this.proxyMode;
                document.getElementById('corsProxyUrl').value = this.customProxyUrl;
                document.getElementById('walletProxyUrl').value = localStorage.getItem('walletProxyUrl') || '';
                UI.updateProfile(); UI.updateSlotDepthLabel(); UI.renderFiatCheckboxes(); UI.onProxyChange(); UI.renderTradeLedger();
            },
            save() {
                localStorage.setItem('qfoam_v22final', JSON.stringify({
                    bankroll: this.bankroll, matrix: this.matrix, level: this.level,
                    qFund: this.qFund, lFund: this.lFund, liveMode: this.liveMode, userCoins: this.userCoins,
                    selectedIntraExchanges: [...this.selectedIntraExchanges],
                    forexRates: this.forexRates, selectedFiats: [...this.selectedFiats],
                    tradeLedger: this.tradeLedger.slice(-15),
                    proxyMode: this.proxyMode, customProxyUrl: this.customProxyUrl,
                    forexLastFetch: this.forexLastFetch
                }));
                localStorage.setItem('wallet_sol', document.getElementById('solAddress').value);
                localStorage.setItem('wallet_eth', document.getElementById('ethAddress').value);
                localStorage.setItem('pumpfun_token', document.getElementById('pumpToken').value);
                localStorage.setItem('basket', document.getElementById('basketInput').value);
                localStorage.setItem('pathDepth', document.getElementById('pathInput').value);
                localStorage.setItem('walletProxyUrl', document.getElementById('walletProxyUrl').value);
            },
            saveWallet() { this.save(); },
            savePumpToken() { document.getElementById('tokenSaved').style.display = 'inline'; this.save(); },
            addTradeToLedger(opp, size, netProfit) {
                const entry = { time: new Date().toISOString(), path: opp.path.join(' → '), size, profit: netProfit, type: opp.type };
                this.tradeLedger.unshift(entry);
                if (this.tradeLedger.length > 15) this.tradeLedger.length = 15;
                this.save(); UI.renderTradeLedger();
            }
        };

        // Built-in public CORS proxy list (rotated on failure)
        const BUILTIN_PROXIES = [
            'https://api.allorigins.win/raw?url=',
            'https://corsproxy.io/?',
            'https://cors.bridged.cc/'
        ];
        let currentProxyIndex = 0;

        function getEffectiveProxyUrl() {
            if (State.proxyMode === 'custom') {
                const custom = (document.getElementById('corsProxyUrl').value || '').trim();
                if (custom && !custom.includes('your-worker') && !custom.includes('placeholder')) return custom;
                return null;
            }
            if (State.proxyMode === 'builtin') return BUILTIN_PROXIES[currentProxyIndex];
            return null; // direct mode
        }

        function rotateProxy() {
            currentProxyIndex = (currentProxyIndex + 1) % BUILTIN_PROXIES.length;
            UI.updateProxyStatus();
        }

        // Robust fetch: try direct, then try each proxy in list
        async function resilientFetch(url, options = {}) {
            // Direct attempt first (unless mode is 'builtin' or 'custom' where we want proxy)
            if (State.proxyMode === 'direct') {
                try {
                    const resp = await fetch(url, options);
                    if (resp.ok) return resp;
                    if (resp.status === 403 || resp.status === 429) throw new Error('Blocked');
                    return resp;
                } catch (e) {
                    // fall through to proxy
                }
            }
            // Try proxies in order
            const proxies = State.proxyMode === 'builtin' ? BUILTIN_PROXIES : 
                          (State.proxyMode === 'custom' ? [getEffectiveProxyUrl()] : BUILTIN_PROXIES);
            for (const proxy of proxies) {
                if (!proxy) continue;
                try {
                    const proxyUrl = proxy + encodeURIComponent(url);
                    const resp = await fetch(proxyUrl, options);
                    if (!resp.ok) continue;
                    // Quick check: if response is text starting with '<' or 'See /corsd', skip
                    const text = await resp.text();
                    if (text.startsWith('<') || text.includes('See /corsd') || text.includes('corsdemo')) {
                        log(`Proxy ${proxy.substring(0,30)} returned non-JSON`, 'warning');
                        continue;
                    }
                    // Return a fake response with the text as json if possible
                    try {
                        const json = JSON.parse(text);
                        return new Response(JSON.stringify(json), { status: 200, headers: { 'Content-Type': 'application/json' } });
                    } catch {
                        return new Response(text, { status: 200, headers: { 'Content-Type': 'text/plain' } });
                    }
                } catch (e) {
                    log(`Proxy ${proxy.substring(0,30)} failed: ${e.message}`, 'warning');
                }
            }
            throw new Error('All fetch attempts exhausted');
        }

        // ====================== KNOWN QUOTE CURRENCIES ======================
        const KNOWN_QUOTES = [
            'USDT', 'USDC', 'BUSD', 'GUSD', 'USD', 'BTC', 'ETH', 'BNB', 'SOL', 'EUR', 'GBP', 'JPY', 'KRW', 'AUD', 'CAD', 'CHF', 'RUR', 'RUB', 'INR', 'TRY', 'BRL', 'IDR', 'DAI', 'SGD', 'PLN', 'UAH', 'AED',
            'BETH', 'ZEC', 'ZRX', 'RAY', 'STRK', 'MATIC', 'DOT', 'TRB', 'TON', 'PI', 'LTC', 'XRP', 'SHIB', 'DOGE', 'BONK', 'PEPE', 'FLOKI', 'WIN', 'SATS', 'NEIRO', 'CAT', 'DUCK', 'BOME', 'OMI', 'DEGEN', 'NOT', 'MEME', 'TOSHI', 'MEW', 'HMSTR', 'XCHNG', 'WBNB', 'RNDR'
        ];
        KNOWN_QUOTES.sort((a, b) => b.length - a.length);

        function parsePairSymbol(rawSymbol) {
            const sym = (rawSymbol || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
            if (!sym) return null;
            for (const quote of KNOWN_QUOTES) {
                if (sym.endsWith(quote) && sym.length > quote.length) {
                    const base = sym.slice(0, sym.length - quote.length);
                    if (base.length >= 1 && base !== quote) return { base, target: quote };
                }
            }
            const parts = sym.split(/[_-]/);
            if (parts.length >= 2 && parts[0] && parts[1]) return { base: parts[0], target: parts[1] };
            return null;
        }

        // ====================== EXCHANGE DEFINITIONS ======================
        const exchangeDefs = [
            { key: 'okx', name: 'OKX', url: 'https://www.okx.com/api/v5/market/tickers?instType=SPOT', type: 'cex', parser: 'okx' },
