                [1, 2, 3].forEach(i => {
                    const strip = document.getElementById('reelStrip' + i);
                    if (!strip || strip.children.length > 0) return;
                    let html = '';
                    for (let j = 0; j < 20; j++) {
                        const sym = symbols[Math.floor(Math.random() * symbols.length)];
