        // ==================== FOREX ====================
        async function fetchForexRates() {
            const fiats = [...State.selectedFiats];
            if (fiats.length === 0) { log('No fiat currencies selected.', 'warning'); return; }
            const vs = fiats.join(',');
            const url = `https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd,${vs}`;
            try {
                const resp = await resilientFetch(url);
                const data = await resp.json();
                if (!data.bitcoin || !data.bitcoin.usd) throw new Error('Invalid response');
                const btcUsd = data.bitcoin.usd;
                State.forexRates = {};
                fiats.forEach(f => { if (data.bitcoin[f]) State.forexRates[f] = btcUsd / data.bitcoin[f]; });
                State.forexLastFetch = Date.now();
                State.save();
                document.getElementById('forexStatus').textContent = `✅ Updated: ${Object.keys(State.forexRates).length} rates`;
                log('Forex rates updated.', 'success');
                displayLowValue();
            } catch (e) { log('Forex fetch failed: ' + e.message, 'error'); }
        }

        function getUsdPrice(pair) {
            if (!pair) return 0;
            if (['USDT', 'USD', 'USDC', 'BUSD', 'GUSD'].includes(pair.target)) return pair.price;
            const rate = State.forexRates[pair.target];
            return rate ? pair.price * rate : pair.price;
        }
        function toUsd(amount, currency) {
            if (!currency || ['USDT', 'USD', 'USDC', 'BUSD', 'GUSD'].includes(currency)) return amount;
            const rate = State.forexRates[currency];
            return rate ? amount * rate : amount;
        }

        // ==================== API LOADERS ====================
        async function loadApi(defKey) {
            const ex = State.exchanges[defKey];
            try {
                let headers = {};
                if (ex.auth) {
                    const token = document.getElementById('pumpToken').value.trim();
                    if (token) headers = { 'Authorization': 'Bearer ' + token };
                }
                const resp = await resilientFetch(ex.url, { headers });
                if (!resp.ok) throw new Error('HTTP ' + resp.status);
                const data = await resp.json();
                let pairs = [];
                switch (ex.parser) {
                    case 'okx':
                        pairs = (data.data || []).slice(0, 600).map(t => {
                            const parts = t.instId.split('-'); if (parts.length !== 2) return null;
                            const price = parseFloat(t.last) || 0, vol = (parseFloat(t.volCcy24h) || 0) * price;
                            return { base: parts[0], target: parts[1], price, volume: vol, liquidity: vol, bidPrice: parseFloat(t.bidPx) || price * 0.999, askPrice: parseFloat(t.askPx) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(Boolean);
                        break;
                    case 'coinbase':
                        pairs = (Array.isArray(data) ? data : []).slice(0, 300).map(p => {
                            const price = parseFloat(p.price) || 1, vol = (parseFloat(p.volume) || 0) * price;
                            return { base: p.base_currency, target: p.quote_currency, price, volume: vol, liquidity: vol, bidPrice: price * 0.998, askPrice: price * 1.002, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p.price > 0);
                        break;
                    case 'binance':
                        pairs = (Array.isArray(data) ? data : []).slice(0, 600).map(t => {
                            const price = parseFloat(t.lastPrice) || 0, vol = (parseFloat(t.quoteVolume) || 0) * price;
                            const parsed = parsePairSymbol(t.symbol || ''); if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol, bidPrice: parseFloat(t.bidPrice) || price * 0.999, askPrice: parseFloat(t.askPrice) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0 && p.base && p.base !== p.target);
                        break;
                    case 'kucoin':
                        pairs = (data?.data?.ticker || []).slice(0, 500).map(t => {
                            const price = parseFloat(t.last) || 0, vol = (parseFloat(t.volValue) || 0) * price;
                            const parsed = parsePairSymbol(t.symbol || ''); if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol, bidPrice: parseFloat(t.buy) || price * 0.999, askPrice: parseFloat(t.sell) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0 && p.base);
                        break;
                    case 'bybit':
                        pairs = (data?.result?.list || []).slice(0, 400).map(t => {
                            const price = parseFloat(t.lastPrice) || 0, vol = (parseFloat(t.volume24h) || 0) * price;
                            const parsed = parsePairSymbol(t.symbol || ''); if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol, bidPrice: parseFloat(t.bid1Price) || price * 0.999, askPrice: parseFloat(t.ask1Price) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
                    case 'gate':
                        pairs = (Array.isArray(data) ? data : []).slice(0, 400).map(t => {
                            const price = parseFloat(t.last) || 0, vol = (parseFloat(t.quote_volume) || 0) * price;
                            const parsed = parsePairSymbol(t.currency_pair || ''); if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol, bidPrice: parseFloat(t.highest_bid) || price * 0.999, askPrice: parseFloat(t.lowest_ask) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0 && p.base);
                        break;
                    case 'mexc':
                        pairs = (Array.isArray(data) ? data : []).slice(0, 400).map(t => {
                            const price = parseFloat(t.lastPrice) || 0, vol = (parseFloat(t.quoteVolume) || 0) * price;
                            const parsed = parsePairSymbol(t.symbol || ''); if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol, bidPrice: parseFloat(t.bidPrice) || price * 0.999, askPrice: parseFloat(t.askPrice) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
                    case 'kraken': {
                        const result = data?.result || {};
                        pairs = Object.keys(result).slice(0, 300).map(k => {
                            const t = result[k]; const price = parseFloat(t.c?.[0]) || 0, vol = (parseFloat(t.v?.[1]) || 0) * price;
                            const parsed = parsePairSymbol(k); if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol, bidPrice: parseFloat(t.b?.[0]) || price * 0.999, askPrice: parseFloat(t.a?.[0]) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
                    }
                    case 'bitstamp':
                        pairs = (Array.isArray(data) ? data : []).slice(0, 250).map(t => {
                            const price = parseFloat(t.last) || 0, vol = (parseFloat(t.volume) || 0) * price;
                            const parts = (t.pair || '').split('/');
                            return { base: parts[0] || '', target: parts[1] || 'USD', price, volume: vol, liquidity: vol, bidPrice: parseFloat(t.bid) || price * 0.999, askPrice: parseFloat(t.ask) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p.price > 0 && p.base);
                        break;
                    case 'indodax': {
                        const tickers = data || {};
                        pairs = Object.keys(tickers).slice(0, 250).map(k => {
                            const t = tickers[k]; const price = parseFloat(t.last) || 0, vol = (parseFloat(t.vol_idr) || 0) * price;
                            const parsed = parsePairSymbol(k); if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol, bidPrice: parseFloat(t.buy) || price * 0.999, askPrice: parseFloat(t.sell) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
                    }
                    case 'yobit': {
                        const info = data?.pairs || {};
                        const allKeys = Object.keys(info).slice(0, 200);
                        if (allKeys.length === 0) throw new Error('No pairs');
                        const tickerUrl = 'https://yobit.net/api/3/ticker/' + allKeys.join('-');
                        const tickerResp = await resilientFetch(tickerUrl);
                        const tickerData = await tickerResp.json();
                        pairs = allKeys.map(k => {
                            const t = tickerData[k] || {}; const price = parseFloat(t.last) || 0, vol = (parseFloat(t.vol) || 0) * price;
                            const parsed = parsePairSymbol(k); if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol, bidPrice: parseFloat(t.buy) || price * 0.999, askPrice: parseFloat(t.sell) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
                    }
                    case 'gemini': {
                        const arr = Array.isArray(data) ? data : [];
                        pairs = arr.map(t => {
                            const rawPair = t.pair || t.symbol || ''; const parsed = parsePairSymbol(rawPair); if (!parsed) return null;
                            const price = parseFloat(t.price) || 0;
                            return { base: parsed.base, target: parsed.target, price, volume: 0, liquidity: price * 100000, bidPrice: price * 0.998, askPrice: price * 1.002, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0 && p.base && p.base != p.target && p.liquidity >= 50);
                        log(`Gemini parsed: ${pairs.length} valid pairs`, 'success');
                        break;
                    }
                    case 'pumpfun':
                        pairs = (Array.isArray(data) ? data : []).map(t => {
                            const price = parseFloat(t.usd_market_cap) / parseFloat(t.total_supply) || 0;
                            const liq = parseFloat(t.usd_market_cap) * 0.1 || 0;
                            return { base: t.symbol || 'UNKNOWN', target: 'SOL', price, volume: liq * 0.5, liquidity: liq, bidPrice: price * 0.95, askPrice: price * 1.05, exchange: defKey, exchangeType: 'cex' };
                        }).filter(p => p.base != 'UNKNOWN' && p.price > 0);
                        if (pairs.length == 0) throw new Error('Empty');
                        break;
                    case 'poloniex':
                        pairs = (Array.isArray(data) ? data : []).slice(0, 400).map(t => {
                            const price = parseFloat(t.close) || 0, vol = (parseFloat(t.quantity) || 0) * price;
                            const parsed = parsePairSymbol(t.symbol || ''); if (!parsed) return null;
                            return { base: parsed.base, target: parsed.target, price, volume: vol, liquidity: vol, bidPrice: parseFloat(t.bid) || price * 0.999, askPrice: parseFloat(t.ask) || price * 1.001, exchange: defKey, exchangeType: ex.type };
                        }).filter(p => p && p.price > 0);
                        break;
