        function applyWsCache(pair) {
            const cache = State.wsTickers[pair.exchange];
            if (cache) { const key = `${pair.base}${pair.target}`.toUpperCase(); const tick = cache[key]; if (tick) return { ...pair, bidPrice: tick.bid || pair.bidPrice, askPrice: tick.ask || pair.askPrice }; }
