        function sanitizeRate(r) { if (!isFinite(r) || r <= 0) return 0; if (r > 1e12) return 1e12; if (r < 1e-15) return 1e-15; return r; }
        function buildGraph() {
            State.graph = {};
            const pairs = getGraphPairs().map(applyWsCache);
            pairs.forEach(p => {
                if (p.liquidity < 50) return; if (!p.base || !p.target || p.base === p.target) return;
                if (!State.graph[p.base]) State.graph[p.base] = {}; if (!State.graph[p.target]) State.graph[p.target] = {};
                const rateBaseToTarget = sanitizeRate(p.bidPrice), rateTargetToBase = sanitizeRate(1 / p.askPrice);
                if (rateBaseToTarget > 0) State.graph[p.base][p.target] = { rate: rateBaseToTarget, weight: -Math.log(rateBaseToTarget), volume: p.volume, liquidity: p.liquidity, exchange: p.exchange, exchangeType: p.exchangeType };
                if (rateTargetToBase > 0) State.graph[p.target][p.base] = { rate: rateTargetToBase, weight: -Math.log(rateTargetToBase), volume: p.volume, liquidity: p.liquidity, exchange: p.exchange, exchangeType: p.exchangeType };
            });
            State.stats.graphNodes = Object.keys(State.graph).length;
            State.stats.graphEdges = Object.values(State.graph).reduce((s, o) => s + Object.keys(o).length, 0);
        }
        function buildTriangles() {
