        // ==================== ARBITRAGE ====================
        function scanTriangular(minProfit = 0.0001) {
            const opps = [], inv = 1000;
            const basket = document.getElementById('basketInput').value.split(',').map(s => s.trim().toUpperCase());
            const filter = document.getElementById('basketTriFilter').checked;
            const mode = document.getElementById('arbMode').value;
            State.triangles.forEach(([A, B, C]) => {
                if (filter && !basket.includes(A)) return;
                const e1 = State.graph[A]?.[B], e2 = State.graph[B]?.[C], e3 = State.graph[C]?.[A];
                if (!e1 || !e2 || !e3) return;
                if (mode === 'intra') { const exs = new Set([e1.exchange, e2.exchange, e3.exchange]); if (exs.size !== 1 || !State.selectedIntraExchanges.has(e1.exchange)) return; }
                const final = inv * e1.rate * e2.rate * e3.rate, profit = final - inv, pct = (profit / inv) * 100;
                if (pct >= minProfit && pct < 50) {
                    const maxSize = Math.min(e1.liquidity, e2.liquidity, e3.liquidity) * 0.05;
                    opps.push({ type: 'triangular', path: [A, B, C, A], profitPercent: pct, actualProfit: toUsd((maxSize / inv) * profit, A), maxTradeSize: toUsd(maxSize, A), edges: [e1, e2, e3] });
                }
            });
            return opps;
        }
        function bellmanFord(startCur, maxPath = 5) {
            const currencies = Object.keys(State.graph); if (!currencies.includes(startCur)) return [];
            const mode = document.getElementById('arbMode').value;
            const dist = {}, pred = {}; currencies.forEach(c => { dist[c] = Infinity; pred[c] = null; }); dist[startCur] = 0;
            for (let i = 0; i < Math.min(maxPath - 1, currencies.length - 1); i++) {
                let updated = false;
                for (const u of currencies) { const nb = State.graph[u]; if (!nb) continue; for (const v in nb) { const w = nb[v].weight; if (dist[u] != Infinity && dist[u] + w < dist[v]) { if (mode === 'intra' && !State.selectedIntraExchanges.has(nb[v].exchange)) continue; dist[v] = dist[u] + w; pred[v] = u; updated = true; } } }
                if (!updated) break;
            }
            const opps = [];
            for (const u of currencies) { const nb = State.graph[u]; if (!nb) continue; for (const v in nb) { if (dist[u] != Infinity && dist[u] + nb[v].weight < dist[v]) { const cycle = reconstructCycle(v, pred, maxPath); if (cycle && cycle[0] === startCur) { const opp = calcCycleOpp(cycle); if (opp) opps.push(opp); } } } }
            return opps;
        }
        function reconstructCycle(start, pred, maxLen) { const cycle = [start]; let cur = start; const visited = new Set(); visited.add(start); for (let i = 0; i < maxLen; i++) { cur = pred[cur]; if (!cur) return null; cycle.push(cur); if (cur === start) return cycle; if (visited.has(cur)) return null; visited.add(cur); } return null; }
        function calcCycleOpp(cycle) {
            let amount = 1000; const edges = []; let totalLiq = Infinity;
            for (let i = 0; i < cycle.length - 1; i++) { const edge = State.graph[cycle[i]]?.[cycle[i + 1]]; if (!edge) return null; amount *= edge.rate; edges.push(edge); totalLiq = Math.min(totalLiq, edge.liquidity); }
            const lastEdge = State.graph[cycle[cycle.length - 1]]?.[cycle[0]]; if (!lastEdge) return null; amount *= lastEdge.rate; edges.push(lastEdge); totalLiq = Math.min(totalLiq, lastEdge.liquidity);
            const profit = amount - 1000, pct = (profit / 1000) * 100;
            if (pct >= 0.0001 && pct < 50 && totalLiq >= 50) { const maxSize = Math.min(...edges.map(e => e.liquidity)) * 0.05; const startCur = cycle[0]; return { type: 'bellman-ford', path: [...cycle, cycle[0]], profitPercent: pct, actualProfit: toUsd((maxSize / 1000) * profit, startCur), maxTradeSize: toUsd(maxSize, startCur), edges }; }
            return null;
        }

