            pairs.forEach(p => { if (p.liquidity < 50) return; if (!p.base || !p.target || p.base === p.target)
                return; if (!State.graph[p.base]) State.graph[p.base] = {}; if (!State.graph[p.target]) State
                .graph[p.target] = {}; const rateBaseToTarget = sanitizeRate(p.bidPrice),
                rateTargetToBase = sanitizeRate(1 / p.askPrice); if (rateBaseToTarget > 0) State.graph[p.base][p
