    <script>
        const audioCtx = new(window.AudioContext || window.webkitAudioContext)();
        function playTone(f, d, t = 'square', v = 0.08) { const o = audioCtx.createOscillator(), g = audioCtx.createGain();
            o.type = t;
            o.frequency.value = f;
            g.gain.setValueAtTime(v, audioCtx.currentTime);
            g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + d);
            o.connect(g);
            g.connect(audioCtx.destination);
            o.start();
            o.stop(audioCtx.currentTime + d); }

        function playSpin() { playTone(800, 0.1, 'sawtooth', 0.04); }

        function playWin() { playTone(523, 0.12);
            setTimeout(() => playTone(659, 0.12), 120);
            setTimeout(() => playTone(784, 0.2), 240); }
        const canvas = document.getElementById('particleCanvas'),
            ctx = canvas.getContext('2d');
        let particles = [];

        function resize() { canvas.width = innerWidth;
            canvas.height = innerHeight; }
        window.addEventListener('resize', resize);
        resize();
        class Particle { constructor(x, y, vx, vy, c, l) { this.x = x;
                this.y = y;
                this.vx = vx;
                this.vy = vy;
                this.color = c;
                this.life = l; } }

        function anim() { ctx.clearRect(0, 0, canvas.width, canvas.height); for (let i = particles.length - 1; i >= 0; i--) {
                const p = particles[i];
                p.x += p.vx;
                p.y += p.vy;
                p.vy += 0.08;
                p.life -= 0.015;
                ctx.fillStyle = p.color;
                ctx.globalAlpha = Math.max(0, p.life);
                ctx.fillRect(p.x, p.y, 4, 4); if (p.life <= 0) particles.splice(i, 1); } requestAnimationFrame(anim); }
        anim();

        function confetti(x, y, n = 35) { const cols = ['#ff00ff', '#00ff00', '#ffd700']; for (let i = 0; i < n; i++) particles
                .push(new Particle(x, y, (Math.random() - 0.5) * 9, (Math.random() - 0.5) * 8 - 4, cols[Math.floor(Math
                    .random() * cols.length)], 0.7 + Math.random() * 0.5)); }

        const State = {
            bankroll: 10000,
            matrix: 0,
            level: 1,
            qFund: 0,
            lFund: 0,
            liveMode: false,
            userCoins: [],
            exchanges: {},
            allPairs: [],
            graph: {},
