        function getEffectiveProxyUrl() { if (State.proxyMode === 'custom') { const c = (document.getElementById(
                    'corsProxyUrl').value || '').trim(); if (c && !c.includes('placeholder')) return c; return null; } if (
                State.proxyMode === 'builtin') return BUILTIN_PROXIES[currentProxyIndex]; return null; }

        function rotateProxy() { currentProxyIndex = (currentProxyIndex + 1) % BUILTIN_PROXIES.length;
            UI.updateProxyStatus(); }

        async function smartFetch(url, options = {}, isCorsSafe = false) {
            // If exchange supports CORS, try direct first
            if (isCorsSafe || State.proxyMode === 'direct') {
                try { const r = await fetch(url, options); if (r.ok) return r; if (r.status >= 400) throw new Error('HTTP ' +
                        r.status); } catch (e) { /* fall through */ }
            }
            const proxy = getEffectiveProxyUrl(); if (proxy) { try { const r = await fetch(proxy + encodeURIComponent(
                    url), options); if (!r.ok) throw new Error('Proxy HTTP ' + r.status); const text = await r
                .text(); if (text.startsWith('<') || text.includes('corsdemo')) throw new Error('Non-JSON'); try { return new
                        Response(JSON.stringify(JSON.parse(text)), { status: 200, headers: { 'Content-Type':
                            'application/json' } }); } catch { return new Response(text, { status: 200, headers: { 'Content-Type': 'text/plain' } }); } } catch (
                e) { rotateProxy(); } }
            throw new Error('All fetch attempts exhausted');
        }

        const KNOWN_QUOTES = [
            'USDT', 'USDC', 'BUSD', 'GUSD', 'USD', 'BTC', 'ETH', 'BNB', 'SOL', 'EUR', 'GBP', 'JPY', 'KRW', 'AUD',
